-- Init migration, generated by concatenating supabase/schemas/01..06 and supabase/storage_policies.sql.
-- The `OWNER TO "supabase_admin"` statements are stripped: migrations run as postgres, which cannot SET ROLE supabase_admin.
-- Regenerate instead of editing by hand.

-- ==== schemas/01_public.sql ====
-- Schema: public (rewritten for Volcren; see PLAN.md)
--
-- Only the HMAC helper and the signed webhook function live here.
-- Apply order: public -> profiles -> scripts -> payments -> stats -> info (scripts.can_access reads payments.accounts at call time)

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
SET default_tablespace = '';
SET default_table_access_method = "heap";

CREATE SCHEMA IF NOT EXISTS "public";

ALTER SCHEMA "public" OWNER TO "pg_database_owner";

COMMENT ON SCHEMA "public" IS 'standard public schema';

CREATE OR REPLACE FUNCTION "public"."generate_hmac"("secret_key" "text", "message" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT encode(extensions.hmac(message::bytea, secret_key::bytea, 'sha256'), 'base64');
$$;


-- Row trigger that POSTs the change to the webapp, signed with an HMAC in
-- X-Supabase-Signature. Both values come from the vault:
--   WEBHOOK_SECRET    HMAC key
--   WEBHOOK_BASE_URL  e.g. https://volcren.com/api/supabase
-- The request goes to <WEBHOOK_BASE_URL>/<schema>/<table>. If either secret is
-- missing the trigger does nothing, so local setups work without the webapp.
CREATE OR REPLACE FUNCTION "public"."webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    secret text;
    base_url text;
    payload jsonb;
    request_id bigint;
BEGIN
    SELECT decrypted_secret INTO secret FROM vault.decrypted_secrets WHERE name = 'WEBHOOK_SECRET' LIMIT 1;
    SELECT decrypted_secret INTO base_url FROM vault.decrypted_secrets WHERE name = 'WEBHOOK_BASE_URL' LIMIT 1;

    IF secret IS NULL OR base_url IS NULL THEN
        RETURN NULL;
    END IF;

    payload := jsonb_build_object(
        'old_record', old,
        'record', new,
        'type', tg_op,
        'table', tg_table_name,
        'schema', tg_table_schema
    );

    SELECT net.http_post(
        format('%s/%s/%s', rtrim(base_url, '/'), tg_table_schema, tg_table_name),
        payload,
        '{}',
        jsonb_build_object(
            'Content-Type', 'application/json',
            'X-Supabase-Signature', public.generate_hmac(secret, payload::text)
        ),
        4000
    ) INTO request_id;

    INSERT INTO supabase_functions.hooks (hook_table_id, hook_name, request_id)
    VALUES (tg_relid, tg_name, request_id);

    RETURN NULL;
END;
$$;


-- Privileges: the webhook runs only from triggers, the HMAC helper only from service_role

REVOKE ALL ON FUNCTION "public"."generate_hmac"("secret_key" "text", "message" "text") FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "public"."webhook"() FROM PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."generate_hmac"("secret_key" "text", "message" "text") TO "service_role";

GRANT USAGE ON SCHEMA "public" TO "postgres", "anon", "authenticated", "service_role";

-- ==== schemas/02_profiles.sql ====
-- Schema: profiles (rewritten by hand for Volcren; see PLAN.md)
-- Apply order: public -> profiles -> scripts -> payments -> stats -> info (scripts.can_access reads payments.accounts at call time)
--
-- Profiles are keyed by auth.users.id. No emails, Stripe IDs or Discord IDs are
-- stored here: provider IDs are read from auth.identities (get_provider_id /
-- get_user_id), and OAuth emails are scrubbed by triggers on the auth tables.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
SET default_tablespace = '';
SET default_table_access_method = "heap";

CREATE SCHEMA IF NOT EXISTS "profiles";

ALTER SCHEMA "profiles" OWNER TO "postgres";

-- Order matters: min_role compares with >=
CREATE TYPE "profiles"."roles" AS ENUM (
    'user',
    'contributor',
    'tester',
    'scripter',
    'moderator',
    'administrator'
);


COMMENT ON TYPE "profiles"."roles" IS 'Profile roles, lowest to highest';

-- Table

CREATE TABLE IF NOT EXISTS "profiles"."profiles" (
    "id" "uuid" NOT NULL,
    "username" "text" NOT NULL,
    "avatar" "text" DEFAULT ''::"text" NOT NULL,
    "role" "profiles"."roles" DEFAULT 'user'::"profiles"."roles" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE ONLY "profiles"."profiles"
    ADD CONSTRAINT "profiles_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "profiles"."profiles"
    ADD CONSTRAINT "profiles_id_fkey" FOREIGN KEY ("id") REFERENCES "auth"."users"("id") ON DELETE CASCADE;

-- Functions

CREATE OR REPLACE FUNCTION "profiles"."uid"() RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT auth.uid();
$$;


CREATE OR REPLACE FUNCTION "profiles"."get_roles_enum"() RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT enum_range(null::profiles.roles)::text[];
$$;


CREATE OR REPLACE FUNCTION "profiles"."is_role"("user_id" "uuid", "target_role" "profiles"."roles") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
  SELECT COALESCE(
    (SELECT p.role = target_role FROM profiles.profiles p WHERE p.id = user_id),
    false
  );
$$;


CREATE OR REPLACE FUNCTION "profiles"."is_role"("target_role" "profiles"."roles") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT profiles.is_role(auth.uid(), target_role);
$$;


CREATE OR REPLACE FUNCTION "profiles"."min_role"("user_id" "uuid", "target_role" "profiles"."roles") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
  SELECT COALESCE(
    (SELECT p.role >= target_role FROM profiles.profiles p WHERE p.id = user_id),
    false
  );
$$;


CREATE OR REPLACE FUNCTION "profiles"."get_provider_id"("user_id" "uuid", "provider" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT i.provider_id
  FROM auth.identities i
  WHERE i.user_id = get_provider_id.user_id AND i.provider = get_provider_id.provider
  LIMIT 1;
$$;


-- Used by the Discord bot (service_role only)
CREATE OR REPLACE FUNCTION "profiles"."get_user_id"("provider" "text", "provider_id" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT i.user_id
  FROM auth.identities i
  WHERE i.provider = get_user_id.provider AND i.provider_id = get_user_id.provider_id
  LIMIT 1;
$$;


-- Sign-up pipeline
--
-- Caveats of the email scrubbing below:
--  * The first JWT issued during an OAuth sign-up, and possibly
--    auth.audit_log_entries.actor_username, can still contain the real email.
--  * The synthetic <id>@volcren.com address applies to OAuth users only; users
--    signing up with the 'email' provider keep their real address.

CREATE OR REPLACE FUNCTION "profiles"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  meta jsonb := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb);
BEGIN
  INSERT INTO profiles.profiles (id, username, avatar)
  VALUES (
    NEW.id,
    COALESCE(
      NULLIF(meta -> 'custom_claims' ->> 'global_name', ''),
      NULLIF(meta ->> 'full_name', ''),
      NULLIF(split_part(meta ->> 'name', '#', 1), ''),
      NULLIF(meta ->> 'user_name', ''),
      'user-' || left(NEW.id::text, 8)
    ),
    COALESCE(
      NULLIF(meta ->> 'avatar_url', ''),
      NULLIF(meta ->> 'picture', ''),
      ''
    )
  );
  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION "profiles"."scrub_user_email"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF COALESCE(NEW.raw_app_meta_data ->> 'provider', '') <> 'email' THEN
    NEW.email := NEW.id::text || '@volcren.com';
    NEW.raw_user_meta_data := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb) - 'email';
  END IF;
  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION "profiles"."scrub_identity_email"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.provider <> 'email' THEN
    NEW.identity_data := NEW.identity_data - 'email';
  END IF;
  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION "profiles"."refresh_avatar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  new_avatar text := COALESCE(
    NULLIF(NEW.raw_user_meta_data ->> 'avatar_url', ''),
    NULLIF(NEW.raw_user_meta_data ->> 'picture', '')
  );
BEGIN
  IF new_avatar IS NOT NULL THEN
    UPDATE profiles.profiles SET avatar = new_avatar
    WHERE id = NEW.id AND avatar IS DISTINCT FROM new_avatar;
  END IF;
  RETURN NULL;
END;
$$;


-- Triggers on auth tables. Both BEFORE triggers run ahead of the AFTER one.
CREATE OR REPLACE TRIGGER "profiles_scrub_user_email" BEFORE INSERT OR UPDATE ON "auth"."users" FOR EACH ROW EXECUTE FUNCTION "profiles"."scrub_user_email"();

CREATE OR REPLACE TRIGGER "profiles_handle_new_user" AFTER INSERT ON "auth"."users" FOR EACH ROW EXECUTE FUNCTION "profiles"."handle_new_user"();

CREATE OR REPLACE TRIGGER "profiles_refresh_avatar" AFTER UPDATE OF "raw_user_meta_data" ON "auth"."users" FOR EACH ROW EXECUTE FUNCTION "profiles"."refresh_avatar"();

CREATE OR REPLACE TRIGGER "profiles_scrub_identity_email" BEFORE INSERT OR UPDATE ON "auth"."identities" FOR EACH ROW EXECUTE FUNCTION "profiles"."scrub_identity_email"();

-- RLS

ALTER TABLE "profiles"."profiles" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "SELECT for EVERYONE" ON "profiles"."profiles" FOR SELECT USING (true);

CREATE POLICY "UPDATE for OWNER" ON "profiles"."profiles" FOR UPDATE TO "authenticated"
    USING (("id" = ( SELECT "auth"."uid"() AS "uid")))
    WITH CHECK (("id" = ( SELECT "auth"."uid"() AS "uid")));

-- Grants

GRANT USAGE ON SCHEMA "profiles" TO "anon";
GRANT USAGE ON SCHEMA "profiles" TO "authenticated";
GRANT USAGE ON SCHEMA "profiles" TO "service_role";

REVOKE ALL ON TABLE "profiles"."profiles" FROM "anon", "authenticated";
GRANT SELECT ON TABLE "profiles"."profiles" TO "anon", "authenticated";
GRANT UPDATE ("username", "avatar") ON TABLE "profiles"."profiles" TO "authenticated";
GRANT ALL ON TABLE "profiles"."profiles" TO "service_role";

-- Functions are executable by PUBLIC by default; lock down the privileged ones.
-- Revoking PUBLIC also drops anon, so the policy helpers are re-granted below.
REVOKE ALL ON FUNCTION "profiles"."handle_new_user"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "profiles"."scrub_user_email"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "profiles"."scrub_identity_email"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "profiles"."refresh_avatar"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "profiles"."get_user_id"("provider" "text", "provider_id" "text") FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "profiles"."get_provider_id"("user_id" "uuid", "provider" "text") FROM PUBLIC, "anon";
GRANT EXECUTE ON FUNCTION "profiles"."get_user_id"("provider" "text", "provider_id" "text") TO "service_role";
GRANT EXECUTE ON FUNCTION "profiles"."get_provider_id"("user_id" "uuid", "provider" "text") TO "authenticated", "service_role";
-- Anonymous visitors need these because RLS policies on other schemas call them
-- (they only expose what the public profiles SELECT policy already shows).
GRANT EXECUTE ON FUNCTION "profiles"."is_role"("user_id" "uuid", "target_role" "profiles"."roles") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "profiles"."min_role"("user_id" "uuid", "target_role" "profiles"."roles") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "profiles"."uid"() TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "profiles"."get_roles_enum"() TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "profiles"."is_role"("target_role" "profiles"."roles") TO "anon", "authenticated", "service_role";

-- ==== schemas/03_scripts.sql ====
-- Schema: scripts (rewritten by hand for Volcren; see PLAN.md)
-- Apply order: public -> profiles -> scripts -> payments -> stats -> info (scripts.can_access reads payments.accounts at call time)
--
-- A script is a set of files (Luau and others) in the `scripts` storage bucket,
-- one folder per revision. Author names/avatars are not copied here: join profiles.profiles.
-- There are no script versions and no Official/Community status.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
SET default_tablespace = '';
SET default_table_access_method = "heap";

CREATE SCHEMA IF NOT EXISTS "scripts";

ALTER SCHEMA "scripts" OWNER TO "postgres";

-- Types

CREATE TYPE "scripts"."category" AS ENUM (
    'combat',
    'boss',
    'minigame',
    'moneymaker',
    'tool',
    'magic',
    'prayer',
    'mining',
    'fishing',
    'woodcutting',
    'hunter',
    'farming',
    'cooking',
    'smithing',
    'fletching',
    'firemaking',
    'herblore',
    'crafting',
    'construction',
    'agility',
    'slayer',
    'thieving',
    'runecrafting',
    'sailing'
);


COMMENT ON TYPE "scripts"."category" IS 'Script categories';

-- Order matters: min_stage/max_stage compare with >=/<=
CREATE TYPE "scripts"."stage" AS ENUM (
    'prototype',
    'alpha',
    'beta',
    'stable',
    'archived'
);


COMMENT ON TYPE "scripts"."stage" IS 'Release lifecycle';

CREATE TYPE "scripts"."type" AS ENUM (
    'premium',
    'free'
);


COMMENT ON TYPE "scripts"."type" IS 'Script type';

-- Tables

CREATE TABLE IF NOT EXISTS "scripts"."scripts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "url" "text" DEFAULT ("gen_random_uuid"())::"text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" NOT NULL,
    "content" "text" NOT NULL,
    "published" boolean DEFAULT false NOT NULL
);


CREATE TABLE IF NOT EXISTS "scripts"."metadata" (
    "id" "uuid" NOT NULL,
    "type" "scripts"."type" DEFAULT 'free'::"scripts"."type" NOT NULL,
    "categories" "scripts"."category"[] DEFAULT '{}'::"scripts"."category"[] NOT NULL,
    "stage" "scripts"."stage" DEFAULT 'prototype'::"scripts"."stage" NOT NULL,
    "price" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "metadata_price_check" CHECK (("price" >= 0) AND (("type" = 'free'::"scripts"."type") = ("price" = 0)))
);

COMMENT ON COLUMN "scripts"."metadata"."price" IS 'Credits (1 credit = 1 cent EUR) charged per minute of use. 0 for free scripts, > 0 for premium ones.';


CREATE TABLE IF NOT EXISTS "scripts"."protected" (
    "id" "uuid" NOT NULL,
    "author" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "revision" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


CREATE TABLE IF NOT EXISTS "scripts"."versions" (
    "id" "uuid" NOT NULL,
    "revision" integer NOT NULL,
    "files" "text"[] NOT NULL,
    CONSTRAINT "versions_files_check" CHECK (cardinality("files") > 0)
);


CREATE TABLE IF NOT EXISTS "scripts"."bundles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "author" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "name" "text" NOT NULL,
    "scripts" "uuid"[] NOT NULL
);


ALTER TABLE ONLY "scripts"."scripts"
    ADD CONSTRAINT "scripts_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "scripts"."scripts"
    ADD CONSTRAINT "scripts_url_key" UNIQUE ("url");

ALTER TABLE ONLY "scripts"."metadata"
    ADD CONSTRAINT "metadata_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "scripts"."protected"
    ADD CONSTRAINT "protected_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "scripts"."versions"
    ADD CONSTRAINT "versions_pkey" PRIMARY KEY ("id", "revision");

ALTER TABLE ONLY "scripts"."bundles"
    ADD CONSTRAINT "bundles_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "scripts"."metadata"
    ADD CONSTRAINT "metadata_id_fkey" FOREIGN KEY ("id") REFERENCES "scripts"."scripts"("id") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY "scripts"."protected"
    ADD CONSTRAINT "protected_id_fkey" FOREIGN KEY ("id") REFERENCES "scripts"."scripts"("id") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY "scripts"."protected"
    ADD CONSTRAINT "protected_author_fkey" FOREIGN KEY ("author") REFERENCES "profiles"."profiles"("id") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY "scripts"."versions"
    ADD CONSTRAINT "versions_id_fkey" FOREIGN KEY ("id") REFERENCES "scripts"."scripts"("id") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY "scripts"."bundles"
    ADD CONSTRAINT "bundles_author_fkey" FOREIGN KEY ("author") REFERENCES "profiles"."profiles"("id") ON UPDATE CASCADE ON DELETE CASCADE;

CREATE INDEX "idx_scripts_protected_author" ON "scripts"."protected" USING "btree" ("author");

CREATE INDEX "idx_scripts_bundles_author" ON "scripts"."bundles" USING "btree" ("author");

-- Helper functions

CREATE OR REPLACE FUNCTION "scripts"."get_revision"("script_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT revision FROM scripts.protected WHERE id = script_id;
$$;


CREATE OR REPLACE FUNCTION "scripts"."is_author"("user_id" "uuid", "script_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM scripts.protected WHERE id = script_id AND author = user_id
  );
$$;


CREATE OR REPLACE FUNCTION "scripts"."is_premium"("script_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM scripts.metadata WHERE id = script_id AND type = 'premium'::scripts.type
  );
$$;


CREATE OR REPLACE FUNCTION "scripts"."is_stage"("script_id" "uuid", "target_stage" "scripts"."stage") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT COALESCE((SELECT stage = target_stage FROM scripts.metadata WHERE id = script_id), false);
$$;


CREATE OR REPLACE FUNCTION "scripts"."max_stage"("script_id" "uuid", "target_stage" "scripts"."stage") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT COALESCE((SELECT stage <= target_stage FROM scripts.metadata WHERE id = script_id), false);
$$;


CREATE OR REPLACE FUNCTION "scripts"."min_stage"("script_id" "uuid", "target_stage" "scripts"."stage") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT COALESCE((SELECT stage >= target_stage FROM scripts.metadata WHERE id = script_id), false);
$$;


-- Access functions (moved from the profiles schema)

-- Premium scripts are open to the author, tester+ and moderator+, and to anyone
-- whose credits cover at least one minute of use. The actual charging happens
-- in payments.charge_usage.
CREATE OR REPLACE FUNCTION "scripts"."can_access"("accesser_id" "uuid", "script_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
      WITH viewer AS (
              SELECT role FROM profiles.profiles WHERE id = accesser_id
      ),
      script AS (
              SELECT p.author, m.type, m.stage, m.price, s.published
              FROM scripts.scripts s
              JOIN scripts.metadata m ON m.id = s.id
              JOIN scripts.protected p ON p.id = s.id
              WHERE s.id = script_id
      )
      SELECT
              (accesser_id IS NOT DISTINCT FROM auth.uid() OR COALESCE(auth.role(), 'service_role') = 'service_role')
              AND COALESCE((
                      SELECT
                              sc.author = accesser_id
                              OR v.role >= 'moderator'::profiles.roles
                              OR (
                                      CASE sc.stage
                                              WHEN 'alpha'::scripts.stage THEN v.role >= 'tester'::profiles.roles
                                              WHEN 'beta'::scripts.stage THEN sc.published
                                              WHEN 'stable'::scripts.stage THEN sc.published
                                              ELSE false
                                      END
                                      AND (
                                              sc.type <> 'premium'::scripts.type
                                              OR v.role >= 'tester'::profiles.roles
                                              OR COALESCE((SELECT a.credits FROM payments.accounts a WHERE a.user_id = accesser_id), 0) >= sc.price
                                      )
                              )
                      FROM script sc
                      LEFT JOIN viewer v ON true
              ), false);
$$;


CREATE OR REPLACE FUNCTION "scripts"."can_access"("script_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
      SELECT scripts.can_access(auth.uid(), script_id);
$$;


CREATE OR REPLACE FUNCTION "scripts"."can_view"("viewer_id" "uuid", "script_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
      SELECT COALESCE((
        SELECT
          p.author = viewer_id
          OR COALESCE(v.role >= 'moderator'::profiles.roles, false)
          OR CASE m.stage
               WHEN 'archived'::scripts.stage THEN false
               WHEN 'prototype'::scripts.stage THEN false
               WHEN 'alpha'::scripts.stage THEN COALESCE(v.role >= 'tester'::profiles.roles, false)
               ELSE s.published
             END
        FROM scripts.scripts s
        LEFT JOIN scripts.protected p ON p.id = s.id
        LEFT JOIN scripts.metadata m ON m.id = s.id
        LEFT JOIN profiles.profiles v ON v.id = viewer_id
        WHERE s.id = script_id
      ), false);
$$;


-- Trigger functions

-- The slug is generated once on insert and never changes afterwards, so URLs
-- survive title and username changes. The id suffix keeps it unique.
CREATE OR REPLACE FUNCTION "scripts"."tr_scripts_pre_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  NEW.url := trim(both '-' from regexp_replace(lower(NEW.title), '[^a-z0-9]+', '-', 'g'))
             || '-' || left(NEW.id::text, 8);
  NEW.url := ltrim(NEW.url, '-');
  RETURN NEW;
END;
$$;


-- Runs as definer so authors cannot insert (or forge) the protected/metadata/
-- versions rows themselves.
CREATE OR REPLACE FUNCTION "scripts"."tr_scripts_post_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
BEGIN
  INSERT INTO scripts.protected (id, author) VALUES (NEW.id, auth.uid());
  INSERT INTO scripts.metadata (id) VALUES (NEW.id);
  INSERT INTO stats.limits (id) VALUES (NEW.id);
  INSERT INTO stats.limits_custom (id) VALUES (NEW.id);
  INSERT INTO stats.values (id) VALUES (NEW.id);
  INSERT INTO stats.values_custom (id) VALUES (NEW.id);
  INSERT INTO stats.website (id) VALUES (NEW.id);

  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION "scripts"."tr_metadata_pre_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.stage < OLD.stage THEN
    RAISE EXCEPTION
      'Invalid stage transition: % → % is not allowed',
      OLD.stage, NEW.stage
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


-- The webapp creates a revision by inserting a versions row (id + files). The
-- revision number is assigned here, atomically, and then the webapp uploads the
-- files to <script id>/<9-digit revision>/<file> in the scripts bucket.
CREATE OR REPLACE FUNCTION "scripts"."tr_versions_pre_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
BEGIN
  UPDATE scripts.protected
  SET revision = revision + 1, updated_at = now()
  WHERE id = NEW.id
  RETURNING revision INTO NEW.revision;

  RETURN NEW;
END;
$$;


-- Triggers

CREATE OR REPLACE TRIGGER "tr_scripts_pre_insert" BEFORE INSERT ON "scripts"."scripts" FOR EACH ROW EXECUTE FUNCTION "scripts"."tr_scripts_pre_insert"();

CREATE OR REPLACE TRIGGER "tr_scripts_post_insert" AFTER INSERT ON "scripts"."scripts" FOR EACH ROW EXECUTE FUNCTION "scripts"."tr_scripts_post_insert"();

CREATE OR REPLACE TRIGGER "tr_metadata_pre_update" BEFORE UPDATE ON "scripts"."metadata" FOR EACH ROW EXECUTE FUNCTION "scripts"."tr_metadata_pre_update"();

CREATE OR REPLACE TRIGGER "tr_versions_pre_insert" BEFORE INSERT ON "scripts"."versions" FOR EACH ROW EXECUTE FUNCTION "scripts"."tr_versions_pre_insert"();

CREATE OR REPLACE TRIGGER "wh-scripts.versions" AFTER INSERT OR DELETE OR UPDATE ON "scripts"."versions" FOR EACH ROW EXECUTE FUNCTION "public"."webhook"();

-- RLS

ALTER TABLE "scripts"."scripts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "scripts"."metadata" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "scripts"."protected" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "scripts"."versions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "scripts"."bundles" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "SELECT for ALLOWED" ON "scripts"."scripts" FOR SELECT USING ("scripts"."can_view"("profiles"."uid"(), "id"));

CREATE POLICY "SELECT for ALLOWED" ON "scripts"."metadata" FOR SELECT USING ("scripts"."can_view"("profiles"."uid"(), "id"));

CREATE POLICY "SELECT for ALLOWED" ON "scripts"."protected" FOR SELECT USING ("scripts"."can_view"("profiles"."uid"(), "id"));

-- Clients only ever use the latest revision. Older rows are kept as history,
-- visible to the author and moderators only.
CREATE POLICY "SELECT for ALLOWED" ON "scripts"."versions" FOR SELECT USING (
    "scripts"."can_view"("profiles"."uid"(), "id")
    AND ("revision" = "scripts"."get_revision"("id")
         OR "scripts"."is_author"("profiles"."uid"(), "id")
         OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles"))
);

CREATE POLICY "SELECT for EVERYONE" ON "scripts"."bundles" FOR SELECT USING (true);

CREATE POLICY "INSERT for SCRIPTER" ON "scripts"."scripts" FOR INSERT TO "authenticated"
    WITH CHECK ("profiles"."min_role"("profiles"."uid"(), 'scripter'::"profiles"."roles"));

CREATE POLICY "INSERT for SCRIPTER" ON "scripts"."bundles" FOR INSERT TO "authenticated"
    WITH CHECK ("author" = "profiles"."uid"() AND "profiles"."min_role"("profiles"."uid"(), 'scripter'::"profiles"."roles"));

CREATE POLICY "UPDATE for AUTHOR" ON "scripts"."scripts" FOR UPDATE TO "authenticated"
    USING (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id")))
    WITH CHECK (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id")));

CREATE POLICY "UPDATE for AUTHOR" ON "scripts"."metadata" FOR UPDATE TO "authenticated"
    USING (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id")))
    WITH CHECK (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id")));

CREATE POLICY "INSERT for AUTHOR" ON "scripts"."versions" FOR INSERT TO "authenticated"
    WITH CHECK (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id")));

CREATE POLICY "UPDATE for AUTHOR" ON "scripts"."bundles" FOR UPDATE TO "authenticated"
    USING (("author" = "profiles"."uid"() OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles")))
    WITH CHECK (("author" = "profiles"."uid"() OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles")));

-- Grants
-- Authors only touch the content columns. ids, urls, authors and revisions are
-- written by triggers or service_role. Revisions are immutable history. There are no DELETE grants for clients.

GRANT USAGE ON SCHEMA "scripts" TO "anon";
GRANT USAGE ON SCHEMA "scripts" TO "authenticated";
GRANT USAGE ON SCHEMA "scripts" TO "service_role";

REVOKE ALL ON TABLE "scripts"."scripts", "scripts"."metadata", "scripts"."protected", "scripts"."versions", "scripts"."bundles" FROM "anon", "authenticated";

GRANT SELECT ON TABLE "scripts"."scripts", "scripts"."metadata", "scripts"."protected", "scripts"."versions", "scripts"."bundles" TO "anon", "authenticated";
GRANT INSERT ("title", "description", "content") ON TABLE "scripts"."scripts" TO "authenticated";
GRANT UPDATE ("title", "description", "content", "published") ON TABLE "scripts"."scripts" TO "authenticated";
GRANT UPDATE ("type", "categories", "stage", "price") ON TABLE "scripts"."metadata" TO "authenticated";
GRANT INSERT ("id", "files") ON TABLE "scripts"."versions" TO "authenticated";
GRANT INSERT ("name", "scripts") ON TABLE "scripts"."bundles" TO "authenticated";
GRANT UPDATE ("name", "scripts") ON TABLE "scripts"."bundles" TO "authenticated";
GRANT ALL ON TABLE "scripts"."scripts", "scripts"."metadata", "scripts"."protected", "scripts"."versions", "scripts"."bundles" TO "service_role";

-- Functions are executable by PUBLIC by default; lock down the privileged ones.
-- The policy helpers stay callable by anon because RLS policies call them.
REVOKE ALL ON FUNCTION "scripts"."tr_scripts_pre_insert"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "scripts"."tr_scripts_post_insert"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "scripts"."tr_metadata_pre_update"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "scripts"."tr_versions_pre_insert"() FROM PUBLIC, "anon", "authenticated";
GRANT EXECUTE ON FUNCTION "scripts"."get_revision"("script_id" "uuid") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."is_author"("user_id" "uuid", "script_id" "uuid") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."is_premium"("script_id" "uuid") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."is_stage"("script_id" "uuid", "target_stage" "scripts"."stage") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."min_stage"("script_id" "uuid", "target_stage" "scripts"."stage") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."max_stage"("script_id" "uuid", "target_stage" "scripts"."stage") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."can_access"("accesser_id" "uuid", "script_id" "uuid") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."can_access"("script_id" "uuid") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "scripts"."can_view"("viewer_id" "uuid", "script_id" "uuid") TO "anon", "authenticated", "service_role";

-- ==== schemas/04_payments.sql ====
-- Schema: payments (new for Volcren; replaces the Stripe schema, see PLAN.md)
-- Apply order: public -> profiles -> scripts -> payments -> stats -> info (scripts.can_access reads payments.accounts at call time)
--
-- Two append-only ledgers per user, both in credits (1 credit = 1 cent EUR):
--   credits_ledger   spendable balance, topped up through payments and spent per minute of script use
--   earnings_ledger  what scripters earned from usage; can be moved into credits (transfer_earnings)
--                    and, later, withdrawn
-- payments.accounts caches both balances. Only the functions below write to it
-- and to the ledgers, and every ledger row stores the balance it resulted in.
-- Ledger and payment rows deliberately have no FK to profiles/scripts: they are
-- financial history and must survive account or script deletion.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
SET default_tablespace = '';
SET default_table_access_method = "heap";

CREATE SCHEMA IF NOT EXISTS "payments";

ALTER SCHEMA "payments" OWNER TO "postgres";

-- Types

CREATE TYPE "payments"."provider" AS ENUM ('bitcart', 'stripe', 'molly');


CREATE TYPE "payments"."payment_status" AS ENUM ('pending', 'paid', 'expired', 'invalid');


CREATE TYPE "payments"."credit_kind" AS ENUM ('topup', 'usage', 'transfer', 'refund', 'adjustment');


CREATE TYPE "payments"."earning_kind" AS ENUM ('sale', 'transfer', 'withdrawal', 'adjustment');


-- Tables

CREATE TABLE IF NOT EXISTS "payments"."config" (
    "id" boolean DEFAULT true NOT NULL,
    "platform_fee_bps" integer DEFAULT 2000 NOT NULL,
    CONSTRAINT "config_singleton" CHECK ("id"),
    CONSTRAINT "config_fee_check" CHECK ("platform_fee_bps" BETWEEN 0 AND 10000)
);


COMMENT ON COLUMN "payments"."config"."platform_fee_bps" IS 'Platform cut of each usage charge in basis points (2000 = 20%).';

INSERT INTO "payments"."config" ("id") VALUES (true) ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS "payments"."accounts" (
    "user_id" "uuid" NOT NULL,
    "credits" bigint DEFAULT 0 NOT NULL,
    "earnings" bigint DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "accounts_credits_check" CHECK ("credits" >= 0),
    CONSTRAINT "accounts_earnings_check" CHECK ("earnings" >= 0)
);


CREATE TABLE IF NOT EXISTS "payments"."payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "provider" "payments"."provider" NOT NULL,
    "provider_id" "text" NOT NULL,
    "status" "payments"."payment_status" DEFAULT 'pending'::"payments"."payment_status" NOT NULL,
    "credits" bigint NOT NULL,
    "currency" "text" DEFAULT 'EUR'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "paid_at" timestamp with time zone,
    CONSTRAINT "payments_credits_check" CHECK ("credits" > 0)
);


COMMENT ON TABLE "payments"."payments" IS 'Provider invoices (Bitcart now, others later). provider_id is the provider''s own invoice id.';

CREATE TABLE IF NOT EXISTS "payments"."credits_ledger" (
    "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" "uuid" NOT NULL,
    "kind" "payments"."credit_kind" NOT NULL,
    "amount" bigint NOT NULL,
    "balance_after" bigint NOT NULL,
    "payment_id" "uuid",
    "script_id" "uuid",
    "minutes" integer,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "credits_ledger_amount_check" CHECK ("amount" <> 0)
);


CREATE TABLE IF NOT EXISTS "payments"."earnings_ledger" (
    "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" "uuid" NOT NULL,
    "kind" "payments"."earning_kind" NOT NULL,
    "amount" bigint NOT NULL,
    "balance_after" bigint NOT NULL,
    "script_id" "uuid",
    "minutes" integer,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "earnings_ledger_amount_check" CHECK ("amount" <> 0)
);


-- Keys

ALTER TABLE ONLY "payments"."config"
    ADD CONSTRAINT "config_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "payments"."accounts"
    ADD CONSTRAINT "accounts_pkey" PRIMARY KEY ("user_id");

ALTER TABLE ONLY "payments"."accounts"
    ADD CONSTRAINT "accounts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "profiles"."profiles"("id") ON DELETE CASCADE;

ALTER TABLE ONLY "payments"."payments"
    ADD CONSTRAINT "payments_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "payments"."payments"
    ADD CONSTRAINT "payments_provider_id_key" UNIQUE ("provider", "provider_id");

ALTER TABLE ONLY "payments"."credits_ledger"
    ADD CONSTRAINT "credits_ledger_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "payments"."credits_ledger"
    ADD CONSTRAINT "credits_ledger_payment_id_fkey" FOREIGN KEY ("payment_id") REFERENCES "payments"."payments"("id");

ALTER TABLE ONLY "payments"."earnings_ledger"
    ADD CONSTRAINT "earnings_ledger_pkey" PRIMARY KEY ("id");

CREATE INDEX "payments_user_id_idx" ON "payments"."payments" USING "btree" ("user_id", "created_at" DESC);

CREATE INDEX "credits_ledger_user_id_idx" ON "payments"."credits_ledger" USING "btree" ("user_id", "id" DESC);

CREATE INDEX "earnings_ledger_user_id_idx" ON "payments"."earnings_ledger" USING "btree" ("user_id", "id" DESC);

CREATE INDEX "earnings_ledger_script_id_idx" ON "payments"."earnings_ledger" USING "btree" ("script_id");

-- Functions

-- Appends a credits_ledger row and updates the cached balance. A negative
-- amount that would overdraw the account fails on accounts_credits_check.
CREATE OR REPLACE FUNCTION "payments"."post_credits"(
    "p_user" "uuid", "p_kind" "payments"."credit_kind", "p_amount" bigint,
    "p_payment" "uuid" DEFAULT NULL, "p_script" "uuid" DEFAULT NULL,
    "p_minutes" integer DEFAULT NULL, "p_note" "text" DEFAULT NULL
) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_balance bigint;
BEGIN
  UPDATE payments.accounts
  SET credits = credits + p_amount, updated_at = now()
  WHERE user_id = p_user
  RETURNING credits INTO v_balance;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no payment account for user %', p_user;
  END IF;

  INSERT INTO payments.credits_ledger (user_id, kind, amount, balance_after, payment_id, script_id, minutes, note)
  VALUES (p_user, p_kind, p_amount, v_balance, p_payment, p_script, p_minutes, p_note);

  RETURN v_balance;
END;
$$;


-- Same for the scripter earnings ledger
CREATE OR REPLACE FUNCTION "payments"."post_earnings"(
    "p_user" "uuid", "p_kind" "payments"."earning_kind", "p_amount" bigint,
    "p_script" "uuid" DEFAULT NULL, "p_minutes" integer DEFAULT NULL, "p_note" "text" DEFAULT NULL
) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_balance bigint;
BEGIN
  UPDATE payments.accounts
  SET earnings = earnings + p_amount, updated_at = now()
  WHERE user_id = p_user
  RETURNING earnings INTO v_balance;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no payment account for user %', p_user;
  END IF;

  INSERT INTO payments.earnings_ledger (user_id, kind, amount, balance_after, script_id, minutes, note)
  VALUES (p_user, p_kind, p_amount, v_balance, p_script, p_minutes, p_note);

  RETURN v_balance;
END;
$$;


-- Called by the API when the provider (Bitcart webhook) reports a payment as
-- paid. Idempotent: returns false if it was already settled.
CREATE OR REPLACE FUNCTION "payments"."settle_payment"("p_payment" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_payment payments.payments;
BEGIN
  SELECT * INTO v_payment FROM payments.payments WHERE id = p_payment FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment % not found', p_payment;
  END IF;

  IF v_payment.status = 'paid' THEN
    RETURN false;
  END IF;

  UPDATE payments.payments SET status = 'paid', paid_at = now() WHERE id = p_payment;

  PERFORM payments.post_credits(v_payment.user_id, 'topup', v_payment.credits, p_payment);

  RETURN true;
END;
$$;


-- Called by the API/loader for every minute (or batch of minutes) a script ran.
-- Debits the user and credits the author's earnings minus the platform fee.
-- Free scripts and users who don't pay (author, tester+) are not charged.
-- Returns the credits charged. Raises 'insufficient credits' if the balance
-- can't cover it.
CREATE OR REPLACE FUNCTION "payments"."charge_usage"("p_user" "uuid", "p_script" "uuid", "p_minutes" integer) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_price integer;
  v_author uuid;
  v_cost bigint;
  v_share bigint;
BEGIN
  IF p_minutes IS NULL OR p_minutes <= 0 THEN
    RAISE EXCEPTION 'minutes must be positive';
  END IF;

  SELECT m.price, p.author INTO v_price, v_author
  FROM scripts.metadata m
  JOIN scripts.protected p ON p.id = m.id
  WHERE m.id = p_script;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'script % not found', p_script;
  END IF;

  IF v_price = 0 OR v_author = p_user OR profiles.min_role(p_user, 'tester'::profiles.roles) THEN
    RETURN 0;
  END IF;

  v_cost := v_price::bigint * p_minutes;

  -- lock the account so concurrent charges can't both pass the check
  PERFORM 1 FROM payments.accounts WHERE user_id = p_user FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no payment account for user %', p_user;
  END IF;

  IF (SELECT credits FROM payments.accounts WHERE user_id = p_user) < v_cost THEN
    RAISE EXCEPTION 'insufficient credits';
  END IF;

  PERFORM payments.post_credits(p_user, 'usage', -v_cost, NULL, p_script, p_minutes);

  v_share := v_cost * (10000 - (SELECT platform_fee_bps FROM payments.config)) / 10000;

  IF v_share > 0 THEN
    PERFORM payments.post_earnings(v_author, 'sale', v_share, p_script, p_minutes);
  END IF;

  RETURN v_cost;
END;
$$;


-- Scripters move their earnings into their spendable credits. Withdrawals
-- will be a separate, service_role flow on the earnings ledger.
CREATE OR REPLACE FUNCTION "payments"."transfer_earnings"("p_amount" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be positive';
  END IF;

  PERFORM payments.post_earnings(v_user, 'transfer', -p_amount, NULL, NULL, 'moved to credits');

  RETURN payments.post_credits(v_user, 'transfer', p_amount, NULL, NULL, NULL, 'moved from earnings');
END;
$$;


-- Trigger functions

CREATE OR REPLACE FUNCTION "payments"."tr_profiles_post_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  INSERT INTO payments.accounts (user_id) VALUES (NEW.id);
  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION "payments"."tr_ledger_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END;
$$;


-- Triggers

CREATE OR REPLACE TRIGGER "tr_profiles_post_insert" AFTER INSERT ON "profiles"."profiles" FOR EACH ROW EXECUTE FUNCTION "payments"."tr_profiles_post_insert"();

CREATE OR REPLACE TRIGGER "tr_ledger_immutable" BEFORE UPDATE OR DELETE ON "payments"."credits_ledger" FOR EACH ROW EXECUTE FUNCTION "payments"."tr_ledger_immutable"();

CREATE OR REPLACE TRIGGER "tr_ledger_immutable" BEFORE UPDATE OR DELETE ON "payments"."earnings_ledger" FOR EACH ROW EXECUTE FUNCTION "payments"."tr_ledger_immutable"();

CREATE OR REPLACE TRIGGER "tr_ledger_truncate" BEFORE TRUNCATE ON "payments"."credits_ledger" FOR EACH STATEMENT EXECUTE FUNCTION "payments"."tr_ledger_immutable"();

CREATE OR REPLACE TRIGGER "tr_ledger_truncate" BEFORE TRUNCATE ON "payments"."earnings_ledger" FOR EACH STATEMENT EXECUTE FUNCTION "payments"."tr_ledger_immutable"();

-- RLS: users read their own rows; everything else goes through the functions

ALTER TABLE "payments"."config" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "payments"."accounts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "payments"."payments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "payments"."credits_ledger" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "payments"."earnings_ledger" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "SELECT for OWNER" ON "payments"."accounts" FOR SELECT TO "authenticated" USING ("user_id" = "profiles"."uid"());

CREATE POLICY "SELECT for OWNER" ON "payments"."payments" FOR SELECT TO "authenticated" USING ("user_id" = "profiles"."uid"());

CREATE POLICY "SELECT for OWNER" ON "payments"."credits_ledger" FOR SELECT TO "authenticated" USING ("user_id" = "profiles"."uid"());

CREATE POLICY "SELECT for OWNER" ON "payments"."earnings_ledger" FOR SELECT TO "authenticated" USING ("user_id" = "profiles"."uid"());

-- Privileges

GRANT USAGE ON SCHEMA "payments" TO "authenticated";
GRANT USAGE ON SCHEMA "payments" TO "service_role";

REVOKE ALL ON TABLE "payments"."config", "payments"."accounts", "payments"."payments", "payments"."credits_ledger", "payments"."earnings_ledger" FROM "anon", "authenticated";

GRANT SELECT ON TABLE "payments"."accounts", "payments"."payments", "payments"."credits_ledger", "payments"."earnings_ledger" TO "authenticated";
GRANT ALL ON TABLE "payments"."config", "payments"."payments" TO "service_role";
GRANT SELECT ON TABLE "payments"."accounts", "payments"."credits_ledger", "payments"."earnings_ledger" TO "service_role";

REVOKE ALL ON FUNCTION "payments"."post_credits"("uuid", "payments"."credit_kind", bigint, "uuid", "uuid", integer, "text") FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "payments"."post_earnings"("uuid", "payments"."earning_kind", bigint, "uuid", integer, "text") FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "payments"."settle_payment"("uuid") FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "payments"."charge_usage"("uuid", "uuid", integer) FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "payments"."transfer_earnings"(bigint) FROM PUBLIC, "anon";
REVOKE ALL ON FUNCTION "payments"."tr_profiles_post_insert"() FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "payments"."tr_ledger_immutable"() FROM PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "payments"."post_credits"("uuid", "payments"."credit_kind", bigint, "uuid", "uuid", integer, "text") TO "service_role";
GRANT EXECUTE ON FUNCTION "payments"."post_earnings"("uuid", "payments"."earning_kind", bigint, "uuid", integer, "text") TO "service_role";
GRANT EXECUTE ON FUNCTION "payments"."settle_payment"("uuid") TO "service_role";
GRANT EXECUTE ON FUNCTION "payments"."charge_usage"("uuid", "uuid", integer) TO "service_role";
GRANT EXECUTE ON FUNCTION "payments"."transfer_earnings"(bigint) TO "authenticated", "service_role";

-- ==== schemas/05_stats.sql ====
-- Schema: stats (rewritten for Volcren; see PLAN.md)
--
-- stats.stats       per-user totals, stats.values / stats.values_custom per-script totals,
-- stats.limits(_custom) per-script sanity limits for the reported values,
-- stats.online      who is running what, stats.website(_monthly) download tracking.
-- Rows for a script are created by scripts.tr_scripts_post_insert. Only
-- service_role writes values; authors may edit their script's limits.
--
-- Visibility: only per-user stats (stats.stats) and the online counts
-- (online_count, online_per_script) are public. Everything else is readable
-- only by the script's author and moderator+ (totals: service_role only).
-- Apply order: public -> profiles -> scripts -> payments -> stats -> info (scripts.can_access reads payments.accounts at call time)

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
SET default_tablespace = '';
SET default_table_access_method = "heap";

CREATE SCHEMA IF NOT EXISTS "stats";

ALTER SCHEMA "stats" OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "stats"."get_level"("experience" bigint) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT floor(experience / (13034431 / 99))::integer;
$$;


CREATE OR REPLACE FUNCTION "stats"."increment_script_stats"("script_id" "uuid", "add_experience" numeric, "add_gold" numeric, "add_runtime" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE stats.values v
  SET experience = v.experience + add_experience,
      gold       = v.gold + add_gold,
      runtime    = v.runtime + add_runtime
  WHERE v.id = script_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No stats row for script %', script_id USING errcode = 'P0002';
  END IF;
END;
$$;


CREATE OR REPLACE FUNCTION "stats"."increment_user_stats"("user_id" "uuid", "add_experience" numeric, "add_gold" numeric, "add_runtime" numeric) RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  INSERT INTO stats.stats AS s (id, experience, gold, runtime)
  VALUES (user_id, add_experience, add_gold, add_runtime)
  ON CONFLICT (id) DO UPDATE
  SET experience = s.experience + excluded.experience,
      gold       = s.gold + excluded.gold,
      runtime    = s.runtime + excluded.runtime;
$$;


-- Tables

CREATE TABLE IF NOT EXISTS "stats"."limits" (
    "id" "uuid" NOT NULL,
    "xp_min" integer DEFAULT 0 NOT NULL,
    "xp_max" integer DEFAULT 0 NOT NULL,
    "gp_min" bigint DEFAULT 0 NOT NULL,
    "gp_max" bigint DEFAULT 0 NOT NULL
);


CREATE TABLE IF NOT EXISTS "stats"."limits_custom" (
    "id" "uuid" NOT NULL,
    "trackers" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "minima" bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    "maxima" bigint[] DEFAULT '{}'::bigint[] NOT NULL
);


COMMENT ON TABLE "stats"."limits_custom" IS 'Custom script stats';

CREATE TABLE IF NOT EXISTS "stats"."online" (
    "script_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "last_seen" timestamp with time zone NOT NULL
);


CREATE TABLE IF NOT EXISTS "stats"."stats" (
    "id" "uuid" NOT NULL,
    "experience" bigint DEFAULT 0 NOT NULL,
    "gold" bigint DEFAULT 0 NOT NULL,
    "runtime" bigint DEFAULT 0 NOT NULL,
    "levels" integer GENERATED ALWAYS AS ("stats"."get_level"("experience")) STORED NOT NULL
);


-- Needs a REFRESH MATERIALIZED VIEW from somewhere (cron/API), it is not refreshed automatically.
CREATE MATERIALIZED VIEW "stats"."totals" AS
 SELECT COALESCE("subquery"."experience", (0)::bigint) AS "experience",
    COALESCE("subquery"."gold", (0)::bigint) AS "gold",
    COALESCE("stats"."get_level"(COALESCE("subquery"."experience", (0)::bigint)), 0) AS "levels",
    COALESCE("subquery"."runtime", (0)::bigint) AS "runtime"
   FROM ( SELECT ("sum"("stats"."experience"))::bigint AS "experience",
            ("sum"("stats"."gold"))::bigint AS "gold",
            ("sum"("stats"."runtime"))::bigint AS "runtime"
           FROM "stats"."stats") "subquery";


CREATE TABLE IF NOT EXISTS "stats"."values" (
    "id" "uuid" NOT NULL,
    "experience" bigint DEFAULT 0 NOT NULL,
    "gold" bigint DEFAULT 0 NOT NULL,
    "runtime" bigint DEFAULT 0 NOT NULL,
    "levels" integer GENERATED ALWAYS AS ("stats"."get_level"("experience")) STORED NOT NULL
);


CREATE TABLE IF NOT EXISTS "stats"."values_custom" (
    "id" "uuid" NOT NULL,
    "values" bigint[] DEFAULT '{}'::bigint[] NOT NULL
);


CREATE TABLE IF NOT EXISTS "stats"."website" (
    "id" "uuid" NOT NULL,
    "downloads" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "total" bigint GENERATED ALWAYS AS (COALESCE("array_length"("downloads", 1), 0)) STORED
);


CREATE TABLE IF NOT EXISTS "stats"."website_monthly" (
    "id" "uuid" NOT NULL,
    "date" timestamp with time zone DEFAULT ("now"() AT TIME ZONE 'utc'::"text") NOT NULL,
    "downloads" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "total" bigint GENERATED ALWAYS AS (COALESCE("array_length"("downloads", 1), 0)) STORED
);


-- Author of the script or moderator+: who may read its private stats and edit its limits
CREATE OR REPLACE FUNCTION "stats"."can_manage"("script_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT scripts.is_author(profiles.uid(), script_id) OR profiles.min_role(profiles.uid(), 'moderator'::profiles.roles);
$$;


-- Public online counts. stats.online itself is private; these expose numbers only.
-- A user counts as online if they were seen in the last 5 minutes (the
-- heartbeat must be more frequent than that).

CREATE OR REPLACE FUNCTION "stats"."online_count"() RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
  SELECT count(DISTINCT user_id) FROM stats.online WHERE last_seen > now() - interval '5 minutes';
$$;


-- Online users per script, only for scripts the caller can view
CREATE OR REPLACE FUNCTION "stats"."online_per_script"() RETURNS TABLE ("script_id" "uuid", "users" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "row_security" TO 'off'
    AS $$
  SELECT o.script_id, count(*)
  FROM stats.online o
  WHERE o.last_seen > now() - interval '5 minutes'
    AND scripts.can_view(profiles.uid(), o.script_id)
  GROUP BY o.script_id;
$$;


