    ADD CONSTRAINT "website_id_fkey" FOREIGN KEY ("id") REFERENCES "scripts"."scripts"("id") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY "stats"."website_monthly"
    ADD CONSTRAINT "website_monthly_id_fkey" FOREIGN KEY ("id") REFERENCES "scripts"."scripts"("id") ON UPDATE CASCADE ON DELETE CASCADE;

-- RLS (service_role bypasses it, so there are no write policies for it)

ALTER TABLE "stats"."limits" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stats"."limits_custom" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stats"."online" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stats"."stats" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stats"."values" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stats"."values_custom" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stats"."website" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stats"."website_monthly" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "SELECT for EVERYONE" ON "stats"."stats" FOR SELECT USING (true);

CREATE POLICY "SELECT for OWNER" ON "stats"."limits" FOR SELECT TO "authenticated" USING ("stats"."can_manage"("id"));

CREATE POLICY "SELECT for OWNER" ON "stats"."limits_custom" FOR SELECT TO "authenticated" USING ("stats"."can_manage"("id"));

CREATE POLICY "SELECT for OWNER" ON "stats"."values" FOR SELECT TO "authenticated" USING ("stats"."can_manage"("id"));

CREATE POLICY "SELECT for OWNER" ON "stats"."values_custom" FOR SELECT TO "authenticated" USING ("stats"."can_manage"("id"));

CREATE POLICY "SELECT for OWNER" ON "stats"."website" FOR SELECT TO "authenticated" USING (("scripts"."is_author"("profiles"."uid"(), "id") OR "profiles"."is_role"("profiles"."uid"(), 'administrator'::"profiles"."roles")));

CREATE POLICY "SELECT for OWNER" ON "stats"."website_monthly" FOR SELECT TO "authenticated" USING (("scripts"."is_author"("profiles"."uid"(), "id") OR "profiles"."is_role"("profiles"."uid"(), 'administrator'::"profiles"."roles")));

CREATE POLICY "SELECT for OWNER" ON "stats"."online" FOR SELECT TO "authenticated" USING ("stats"."can_manage"("script_id"));

CREATE POLICY "UPDATE for OWNER" ON "stats"."limits" FOR UPDATE TO "authenticated" USING (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id"))) WITH CHECK (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id")));

CREATE POLICY "UPDATE for OWNER" ON "stats"."limits_custom" FOR UPDATE TO "authenticated" USING (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id"))) WITH CHECK (("profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles") OR "scripts"."is_author"("profiles"."uid"(), "id")));

-- Privileges

GRANT USAGE ON SCHEMA "stats" TO "anon", "authenticated", "service_role";

REVOKE ALL ON TABLE "stats"."limits", "stats"."limits_custom", "stats"."online", "stats"."stats", "stats"."totals", "stats"."values", "stats"."values_custom", "stats"."website", "stats"."website_monthly" FROM "anon", "authenticated";

GRANT SELECT ON TABLE "stats"."stats" TO "anon", "authenticated";
GRANT SELECT ON TABLE "stats"."limits", "stats"."limits_custom", "stats"."online", "stats"."values", "stats"."values_custom", "stats"."website", "stats"."website_monthly" TO "authenticated";
GRANT UPDATE ("xp_min", "xp_max", "gp_min", "gp_max") ON TABLE "stats"."limits" TO "authenticated";
GRANT UPDATE ("trackers", "minima", "maxima") ON TABLE "stats"."limits_custom" TO "authenticated";
GRANT ALL ON TABLE "stats"."limits", "stats"."limits_custom", "stats"."online", "stats"."stats", "stats"."totals", "stats"."values", "stats"."values_custom", "stats"."website", "stats"."website_monthly" TO "service_role";

REVOKE ALL ON FUNCTION "stats"."increment_script_stats"("script_id" "uuid", "add_experience" numeric, "add_gold" numeric, "add_runtime" numeric) FROM PUBLIC, "anon", "authenticated";
REVOKE ALL ON FUNCTION "stats"."increment_user_stats"("user_id" "uuid", "add_experience" numeric, "add_gold" numeric, "add_runtime" numeric) FROM PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "stats"."can_manage"("script_id" "uuid") TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "stats"."online_count"() TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "stats"."online_per_script"() TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "stats"."get_level"("experience" bigint) TO "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "stats"."increment_script_stats"("script_id" "uuid", "add_experience" numeric, "add_gold" numeric, "add_runtime" numeric) TO "service_role";
GRANT EXECUTE ON FUNCTION "stats"."increment_user_stats"("user_id" "uuid", "add_experience" numeric, "add_gold" numeric, "add_runtime" numeric) TO "service_role";

-- ==== schemas/06_info.sql ====
-- Schema: info (rewritten for Volcren; see PLAN.md)
--
-- Legal documents, one row per published version. The old privacy_policy,
-- user_tos and scripter_tos tables (identical shape) are merged into
-- info.documents. The latest version of a kind is the current one.
-- Apply order: public -> profiles -> scripts -> payments -> stats -> info (scripts.can_access reads payments.accounts at call time)

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
SET default_tablespace = '';
SET default_table_access_method = "heap";

CREATE SCHEMA IF NOT EXISTS "info";

ALTER SCHEMA "info" OWNER TO "postgres";

CREATE TYPE "info"."kind" AS ENUM (
    'privacy_policy',
    'user_tos',
    'scripter_tos'
);


CREATE TABLE IF NOT EXISTS "info"."documents" (
    "kind" "info"."kind" NOT NULL,
    "version" integer NOT NULL,
    "content" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE ONLY "info"."documents"
    ADD CONSTRAINT "documents_pkey" PRIMARY KEY ("kind", "version");

-- Versions count up per kind, starting at 1. Published documents are
-- immutable: there is no UPDATE or DELETE grant.
CREATE OR REPLACE FUNCTION "info"."tr_documents_pre_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('info.documents.' || NEW.kind::text));

  SELECT COALESCE(max(version), 0) + 1 INTO NEW.version FROM info.documents WHERE kind = NEW.kind;

  RETURN NEW;
END;
$$;


CREATE OR REPLACE TRIGGER "tr_documents_pre_insert" BEFORE INSERT ON "info"."documents" FOR EACH ROW EXECUTE FUNCTION "info"."tr_documents_pre_insert"();

ALTER TABLE "info"."documents" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "SELECT for EVERYONE" ON "info"."documents" FOR SELECT USING (true);

CREATE POLICY "INSERT for ADMINISTRATOR" ON "info"."documents" FOR INSERT TO "authenticated" WITH CHECK ("profiles"."is_role"('administrator'::"profiles"."roles"));

GRANT USAGE ON SCHEMA "info" TO "anon", "authenticated", "service_role";

REVOKE ALL ON TABLE "info"."documents" FROM "anon", "authenticated";

GRANT SELECT ON TABLE "info"."documents" TO "anon", "authenticated";
GRANT INSERT ("kind", "content") ON TABLE "info"."documents" TO "authenticated";
GRANT ALL ON TABLE "info"."documents" TO "service_role";

REVOKE ALL ON FUNCTION "info"."tr_documents_pre_insert"() FROM PUBLIC, "anon", "authenticated";

-- ==== storage_policies.sql ====
-- RLS policies for Supabase's storage schema (rewritten for Volcren; see PLAN.md).
-- Apply after the schemas (policies call scripts.* and profiles.* functions).
--
-- Buckets:
--   scripts   <script id>/<9-digit revision>/<file>. Authors upload to the current revision
--             folder only; others read the current revision if scripts.can_access allows it.
--   imgs      scripts/<script id>/cover.webp and banner.webp, public read, author write.
--   assets    public read, service_role write.
--   launcher  public read, service_role write (launcher releases).

CREATE POLICY "scripts DELETE for supabase_admin" ON "storage"."objects" FOR DELETE USING ((("bucket_id" = 'scripts'::"text") AND (CURRENT_USER = 'supabase_admin'::"name")));

CREATE POLICY "scripts INSERT for author" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK ((("bucket_id" = 'scripts'::"text") AND ("scripts"."is_author"("profiles"."uid"(), (("storage"."foldername"("name"))[1])::"uuid") OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles")) AND (("storage"."foldername"("name"))[2] = "lpad"(("scripts"."get_revision"((("storage"."foldername"("name"))[1])::"uuid"))::"text", 9, '0'))));

CREATE POLICY "scripts SELECT for allowed" ON "storage"."objects" FOR SELECT TO "authenticated" USING ((("bucket_id" = 'scripts'::"text") AND "scripts"."can_access"("profiles"."uid"(), (("storage"."foldername"("name"))[1])::"uuid") AND (("storage"."foldername"("name"))[2] = "lpad"(("scripts"."get_revision"((("storage"."foldername"("name"))[1])::"uuid"))::"text", 9, '0') OR "scripts"."is_author"("profiles"."uid"(), (("storage"."foldername"("name"))[1])::"uuid") OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles"))));

CREATE POLICY "imgs INSERT for author" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK ((("bucket_id" = 'imgs'::"text") AND ((("array_length"("storage"."foldername"("name"), 1) = 2) AND (("storage"."foldername"("name"))[1] = 'scripts'::"text") AND ("storage"."filename"("name") = ANY (ARRAY['cover.webp'::"text", 'banner.webp'::"text"])) AND "scripts"."is_author"("profiles"."uid"(), (("storage"."foldername"("name"))[2])::"uuid")) OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles"))));

CREATE POLICY "imgs UPDATE for author" ON "storage"."objects" FOR UPDATE USING ((("bucket_id" = 'imgs'::"text") AND ((("array_length"("storage"."foldername"("name"), 1) = 2) AND (("storage"."foldername"("name"))[1] = 'scripts'::"text") AND ("storage"."filename"("name") = ANY (ARRAY['cover.webp'::"text", 'banner.webp'::"text"])) AND "scripts"."is_author"("profiles"."uid"(), (("storage"."foldername"("name"))[2])::"uuid")) OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles")))) WITH CHECK ((("bucket_id" = 'imgs'::"text") AND ((("array_length"("storage"."foldername"("name"), 1) = 2) AND (("storage"."foldername"("name"))[1] = 'scripts'::"text") AND ("storage"."filename"("name") = ANY (ARRAY['cover.webp'::"text", 'banner.webp'::"text"])) AND "scripts"."is_author"("profiles"."uid"(), (("storage"."foldername"("name"))[2])::"uuid")) OR "profiles"."min_role"("profiles"."uid"(), 'moderator'::"profiles"."roles"))));

CREATE POLICY "imgs SELECT for everyone" ON "storage"."objects" FOR SELECT USING (("bucket_id" = 'imgs'::"text"));

CREATE POLICY "assets INSERT for service_role" ON "storage"."objects" FOR INSERT TO "service_role" WITH CHECK (("bucket_id" = 'assets'::"text"));

CREATE POLICY "assets UPDATE for service_role" ON "storage"."objects" FOR UPDATE TO "service_role" USING (("bucket_id" = 'assets'::"text")) WITH CHECK (("bucket_id" = 'assets'::"text"));

CREATE POLICY "assets SELECT for everyone" ON "storage"."objects" FOR SELECT USING (("bucket_id" = 'assets'::"text"));

CREATE POLICY "launcher INSERT for service_role" ON "storage"."objects" FOR INSERT TO "service_role" WITH CHECK (("bucket_id" = 'launcher'::"text"));

CREATE POLICY "launcher UPDATE for service_role" ON "storage"."objects" FOR UPDATE TO "service_role" USING (("bucket_id" = 'launcher'::"text")) WITH CHECK (("bucket_id" = 'launcher'::"text"));

CREATE POLICY "launcher SELECT for everyone" ON "storage"."objects" FOR SELECT USING (("bucket_id" = 'launcher'::"text"));

